CREATE TABLE "accounts" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7() NOT NULL,
	"user_id" uuid NOT NULL,
	"type" "account_type" NOT NULL,
	"provider_name" text NOT NULL,
	"logo_key" text,
	"display_name" varchar(40) NOT NULL,
	"last4" char(4),
	"phone_masked" text,
	"currency" char(3) NOT NULL,
	"opening_balance_minor" bigint DEFAULT 0 NOT NULL,
	"opening_date" date NOT NULL,
	"color" text NOT NULL,
	"include_in_available" boolean DEFAULT true NOT NULL,
	"show_as_card" boolean DEFAULT false NOT NULL,
	"is_default_quick_entry" boolean DEFAULT false NOT NULL,
	"sort_order" integer DEFAULT 0 NOT NULL,
	"status" "account_status" DEFAULT 'active' NOT NULL,
	"archived_at" timestamp with time zone,
	"low_balance_threshold_minor" bigint,
	"last_reconciled_at" timestamp with time zone,
	"cc_limit_minor" bigint,
	"cc_statement_day" smallint,
	"cc_due_day" smallint,
	"parent_account_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "accounts_user_id_id_key" UNIQUE("user_id","id"),
	CONSTRAINT "accounts_currency_check" CHECK ("accounts"."currency" ~ '^[A-Z]{3}$'),
	CONSTRAINT "accounts_last4_check" CHECK ("accounts"."last4" ~ '^[0-9]{4}$'),
	CONSTRAINT "accounts_cc_days_check" CHECK ("accounts"."cc_statement_day" between 1 and 31 and "accounts"."cc_due_day" between 1 and 31),
	CONSTRAINT "accounts_archived_check" CHECK (("accounts"."status" = 'archived') = ("accounts"."archived_at" is not null)),
	CONSTRAINT "accounts_default_active_check" CHECK (not "accounts"."is_default_quick_entry" or "accounts"."status" = 'active')
);
