-- At most five tags per transaction (FR-K3). The lock on the transaction row serialises concurrent inserts.
CREATE FUNCTION transaction_tags_limit() RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  PERFORM 1 FROM public.transactions WHERE user_id = NEW.user_id AND id = NEW.transaction_id FOR UPDATE;
  IF (SELECT count(*) FROM public.transaction_tags WHERE transaction_id = NEW.transaction_id) >= 5 THEN
    RAISE EXCEPTION 'a transaction has at most 5 tags' USING ERRCODE = 'check_violation',
      CONSTRAINT = 'transaction_tags_limit';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER transaction_tags_limit BEFORE INSERT ON transaction_tags
  FOR EACH ROW EXECUTE FUNCTION transaction_tags_limit();
--> statement-breakpoint

-- The fx job fetches rates for every currency in use. The worker cannot see other users' accounts, so it calls this
-- SECURITY DEFINER function, which returns only currency codes (no user data). It runs as its owner wf_migrate, for
-- which FORCE ROW LEVEL SECURITY applies too; the read policies below let exactly this function's queries through.
CREATE POLICY accounts_currencies_in_use ON accounts FOR SELECT TO wf_migrate USING (true);
--> statement-breakpoint
CREATE POLICY users_currencies_in_use ON users FOR SELECT TO wf_migrate USING (true);
--> statement-breakpoint
CREATE POLICY fx_rates_currencies_in_use ON fx_rates FOR SELECT TO wf_migrate USING (true);
--> statement-breakpoint
CREATE FUNCTION fx_currencies_in_use() RETURNS SETOF char(3)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
  SELECT currency FROM public.accounts
  UNION SELECT base_currency FROM public.users
  UNION SELECT base FROM public.fx_rates WHERE user_id IS NOT NULL
  UNION SELECT quote FROM public.fx_rates WHERE user_id IS NOT NULL
  ORDER BY 1
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION fx_currencies_in_use() FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION fx_currencies_in_use() TO wf_worker;
